    import sys
    import sys
    n, k = map(int, sys.stdin.read().strip().split())
    if k == 1:
        print(' '.join(map(str, range(1, n + 1))))
    else:
        result = [1]
        used = {1}
        sign = 1
        current = 1
        for diff in range(k, 0, -1):
            current += sign * diff
            result.append(current)
            used.add(current)
            sign *= -1
        for i in range(2, n + 1):
            if i not in used:
                result.append(i)
        print(' '.join(map(str, result)))

